#!/bin/bash
# Claude Code status line — Dracula theme
# Installed by the cc-statusline skill (https://github.com/jackieyyang/skills).
# Originally generated by webup-statusline (https://github.com/webup/skills-cc), then customized.

# Ensure jq is available (Windows: WinGet/scoop installs may not be on PATH)
if ! command -v jq >/dev/null 2>&1; then
  for _jq_dir in \
    "/c/Users/$USERNAME/AppData/Local/Microsoft/WinGet/Links" \
    "/c/Users/$USERNAME/AppData/Local/Microsoft/WinGet/Packages/jqlang.jq_Microsoft.Winget.Source_8wekyb3d8bbwe" \
    "$HOME/scoop/shims" \
  ; do
    if [ -d "$_jq_dir" ] && { [ -x "$_jq_dir/jq" ] || [ -x "$_jq_dir/jq.exe" ]; }; then
      export PATH="$PATH:$_jq_dir"
      break
    fi
  done
  if ! command -v jq >/dev/null 2>&1; then
    echo "claude-status: jq is required but not installed." >&2
    echo "  Install via: winget install jqlang.jq  OR  scoop install jq" >&2
    exit 1
  fi
fi
# Colors
readonly RST='\033[0m'
readonly C_MODEL='\033[38;2;189;147;249m'
readonly C_CTX_OK='\033[38;2;80;250;123m'
readonly C_CTX_WARN='\033[38;2;241;250;140m'
readonly C_CTX_LOW='\033[38;2;255;85;85m'
readonly C_BAR_EMPTY='\033[38;2;68;71;90m'
readonly C_PCT='\033[38;2;248;248;242m'
readonly C_DIR='\033[38;2;139;233;253m'
readonly C_GIT='\033[38;2;255;184;108m'
readonly C_GIT_DIRTY='\033[38;2;241;250;140m'
readonly C_VIM='\033[38;2;241;250;140m'
readonly C_WORKTREE='\033[38;2;255;121;198m'
readonly C_STYLE='\033[38;2;189;147;249m'
readonly C_COST='\033[38;2;255;215;0m'
readonly C_EFFORT_HIGH='\033[1;38;2;255;85;85m'
readonly C_EFFORT_MED='\033[38;2;241;250;140m'
readonly C_EFFORT_LOW='\033[38;2;80;250;123m'
readonly C_EFFORT_OFF='\033[2;38;2;98;114;164m'
readonly C_SEP='\033[38;2;98;114;164m'

readonly SEP=" | "

# Read JSON from stdin
input=$(cat)

# Parse every field in a single jq pass (one process instead of ~20).
# Numbers are pre-formatted here so the rest of the script needs no awk/date calls.
# Fields are joined with \x1f so empty values keep their position.
IFS=$'\x1f' read -r model remaining ctx_used_k ctx_total_k effort model_id current_dir \
  original_repo_dir output_style cost_formatted worktree_name worktree_branch \
  rl_5h_pct rl_5h_left rl_5h_at rl_7d_pct rl_7d_left rl_7d_at <<< "$(echo "$input" | jq -r '
  def s: if . == null then "" else tostring end;
  def k: if . == null then "" else (. / 1000 | round | tostring) + "k" end;
  def pad2: tostring | if length < 2 then "0" + . else . end;
  def pct: if . == null then "" else (. + 0.5 | floor | tostring) end;
  def countdown: if . == null then "" else (. - now | floor) as $l
    | if $l <= 0 then ""
      elif $l >= 86400 then "\($l / 86400 | floor)d\($l % 86400 / 3600 | floor)h"
      elif $l >= 3600 then "\($l / 3600 | floor)h\($l % 3600 / 60 | floor | pad2)m"
      else "\($l / 60 | floor)m" end end;
  def at($fmt): if . == null then "" else (floor | strflocaltime($fmt)) end;
  def cost: if . == null or . < 0.005 then ""
    else (. * 100 | round) as $c | "$\($c / 100 | floor).\($c % 100 | pad2)" end;
  [ (.model.display_name | s),
    (.context_window.remaining_percentage | if . == null then "" else (floor | tostring) end),
    (.context_window.total_input_tokens | k),
    (.context_window.context_window_size | k),
    (.effort.level | s),
    (.model.id | s),
    (.workspace.current_dir | s),
    (.worktree.original_repo_dir | s),
    (.output_style.name | s),
    (.cost.total_cost_usd | cost),
    (.worktree.name | s),
    (.worktree.branch | s),
    (.rate_limits.five_hour.used_percentage | pct),
    (.rate_limits.five_hour.resets_at | countdown),
    (.rate_limits.five_hour.resets_at | at("%H:%M")),
    (.rate_limits.seven_day.used_percentage | pct),
    (.rate_limits.seven_day.resets_at | countdown),
    (.rate_limits.seven_day.resets_at | at("%m/%d %H:%M"))
  ] | map(gsub("[\u001f\n]"; " ")) | join("\u001f")')"

# Effort level: prefer the live value from stdin, fall back to settings (local overrides global)
for f in "$HOME/.claude/settings.local.json" "$HOME/.claude/.claude/settings.local.json" "$HOME/.claude/settings.json"; do
  if [ -z "$effort" ] && [ -f "$f" ]; then
    effort=$(jq -r --arg m "$model_id" '.modelSettings[$m].effortLevel // .effortLevel // empty' "$f" 2>/dev/null)
  fi
done

# Git info: one rev-parse tells us both "is this a repo" and "is this a worktree"
is_worktree=0
[ -n "$worktree_name" ] && is_worktree=1
git_branch="$worktree_branch"
git_dirty=0
if [ -n "$current_dir" ] && _git_dirs=$(git -C "$current_dir" --no-optional-locks rev-parse --git-dir --git-common-dir 2>/dev/null); then
  _gd=${_git_dirs%%$'\n'*}
  _gcd=${_git_dirs#*$'\n'}
  # Worktree detection (git fallback for external worktrees)
  if [ "$is_worktree" -eq 0 ] && [ -n "$_gd" ] && [ -n "$_gcd" ] && [ "$_gd" != "$_gcd" ]; then
    is_worktree=1
    # Use parent dir basename as worktree id (e.g. ~/.codex/worktrees/46a6/clawmaster -> 46a6)
    _parent=${current_dir%/*}
    worktree_name=${_parent##*/}
    # Fall back to current dir basename if parent is a generic bucket
    case "$worktree_name" in
      worktrees|wt|.codex|.claude) worktree_name=${current_dir##*/} ;;
    esac
  fi
  # Git branch (prefer worktree.branch from input, fall back to git CLI)
  if [ -z "$git_branch" ]; then
    git_branch=$(git -C "$current_dir" --no-optional-locks branch --show-current 2>/dev/null)
  fi
  # Dirty = staged or unstaged changes to tracked files (untracked files ignored)
  if [ -n "$git_branch" ] && [ -n "$(git -C "$current_dir" --no-optional-locks status --porcelain -uno 2>/dev/null)" ]; then
    git_dirty=1
  fi
fi

# Shorten directory (prefer original repo when in a worktree)
short_dir=""
if [ -n "$original_repo_dir" ]; then
  short_dir=${original_repo_dir##*/}
elif [ -n "$current_dir" ]; then
  short_dir=${current_dir##*/}
fi

# Progress bar (color scales with remaining context)
bar=""
if [ -n "$remaining" ]; then
  used=$((100 - remaining))
  filled=$((used / 5))
  empty=$((20 - filled))
  if [ "$remaining" -lt 20 ]; then
    ctx_color="$C_CTX_LOW"
  elif [ "$remaining" -lt 50 ]; then
    ctx_color="$C_CTX_WARN"
  else
    ctx_color="$C_CTX_OK"
  fi
  bar="${C_SEP}[${RST}"
  for ((i=0; i<filled; i++)); do bar+="${ctx_color}■${RST}"; done
  for ((i=0; i<empty; i++)); do bar+="${C_BAR_EMPTY}□${RST}"; done
  bar+="${C_SEP}]${RST} ${ctx_color}${used}%${RST}"
  # Append token counts when available: used_tokens/window_size
  if [ -n "$ctx_used_k" ] && [ -n "$ctx_total_k" ]; then
    bar+="${C_SEP} (${RST}${ctx_color}${ctx_used_k}${RST}${C_SEP}/${RST}${ctx_color}${ctx_total_k}${RST}${C_SEP})${RST}"
  fi
fi

# Assemble
parts=()

if [ -n "$model" ]; then
  parts+=("${C_MODEL}◈ ${model}${RST}")
fi

if [ -n "$bar" ]; then
  parts+=("${bar}")
fi

if [ -n "$cost_formatted" ]; then
  parts+=("${C_COST}${cost_formatted}${RST}")
fi

# Color effort by level (max/xhigh/high share the bold-red pressure tier)
if [ -n "$effort" ]; then
  case "$effort" in
    max|MAX|Max|xhigh|XHIGH|XHigh|high|High|HIGH)  effort_color="$C_EFFORT_HIGH" ;;
    medium|Medium|MEDIUM)                          effort_color="$C_EFFORT_MED" ;;
    low|Low|LOW|xlow|XLow|XLOW|minimal|Minimal)    effort_color="$C_EFFORT_LOW" ;;
    *)                                             effort_color="$C_EFFORT_OFF" ;;
  esac
  parts+=("${effort_color}↯ ${effort}${RST}")
fi

if [ -n "$output_style" ] && [ "$output_style" != "default" ]; then
  parts+=("${C_STYLE}❋ ${output_style}${RST}")
fi

if [ -n "$short_dir" ]; then
  parts+=("${C_DIR}⌂ ${short_dir}${RST}")
fi

if [ "$is_worktree" -eq 1 ] && [ -n "$worktree_name" ]; then
  parts+=("\033[1m${C_WORKTREE}⊕ worktree:${worktree_name}${RST}")
fi

if [ -n "$git_branch" ]; then
  if [ "$git_dirty" -eq 1 ]; then
    parts+=("${C_GIT_DIRTY}⎇ ${git_branch}${RST}")
  else
    parts+=("${C_GIT}⎇ ${git_branch}${RST}")
  fi
fi

# Output
output=""
for i in "${!parts[@]}"; do
  if [ "$i" -gt 0 ]; then
    output+="${C_SEP}${SEP}${RST}"
  fi
  output+="${parts[$i]}"
done

# Line 2: rate limits (5h / 7d quota)
readonly C_QUOTA_LABEL='\033[38;2;189;147;249m'
line2=""
quota_part() {
  # $1 = label, $2 = used % (rounded), $3 = countdown, $4 = reset time; appends to line2
  local label="$1" pct="$2" color filled i
  if [ "$pct" -ge 80 ]; then color="$C_CTX_LOW"
  elif [ "$pct" -ge 50 ]; then color="$C_CTX_WARN"
  else color="$C_CTX_OK"; fi
  filled=$(( (pct + 5) / 10 )); [ "$filled" -gt 10 ] && filled=10
  [ -n "$line2" ] && line2+="${C_SEP}${SEP}${RST}"
  line2+="${C_QUOTA_LABEL}◷ ${label}${RST} "
  for ((i=0; i<filled; i++)); do line2+="${color}▰${RST}"; done
  for ((i=filled; i<10; i++)); do line2+="${C_BAR_EMPTY}▱${RST}"; done
  printf -v pct '%3d' "$pct"
  line2+=" ${color}${pct}%${RST}"
  if [ -n "$3" ]; then
    line2+="${C_SEP} ↻ $3 ($4)${RST}"
  fi
}

[ -n "$rl_5h_pct" ] && quota_part "5h" "$rl_5h_pct" "$rl_5h_left" "$rl_5h_at"
[ -n "$rl_7d_pct" ] && quota_part "7d" "$rl_7d_pct" "$rl_7d_left" "$rl_7d_at"
if [ -n "$line2" ]; then
  output+="\n${line2}"
fi

printf "%b" "$output"
